<script setup>
import { assetUrl } from '../lib/assets.js'
import { computed, ref, onBeforeUnmount } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { Layers,CalendarDays,Users,ShieldCheck,LockKeyhole,MessageCircle,Star,ArrowRight,Info } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import { state,taskById,money,income,addOrder } from '../lib/store'
import { requireRole,notify } from '../lib/actions'
import StatusBadge from '../components/StatusBadge.vue'
const route=useRoute(),router=useRouter(),task=computed(()=>taskById(route.params.id))
const saved=computed(()=>state.bookmarks.includes(task.value?.id)),available=computed(()=>(!task.value?.status||task.value.status==='招募中')&&(task.value.mode==='比稿'||(task.value.filled||0)<(task.value.capacity||1)))
const confirmation=ref(false),seconds=ref(3);let timer
function bookmark(){const id=task.value.id;state.bookmarks=saved.value?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];notify(saved.value?'任务已收藏':'已取消收藏')}
function accept(){
 if(!requireRole(router,'creator',true))return
 if(!available.value)return
 if(task.value.mode==='比稿'){router.push(`/tasks/${task.value.id}/bid`);return}
 if(state.orders.some(o=>o.taskId===task.value.id&&!['已取消','已完成'].includes(o.status))){ElMessage.info('你已有该任务的进行中订单');router.push(`/creator/orders/${state.orders.find(o=>o.taskId===task.value.id).id}`);return}
 confirmation.value=true;seconds.value=3;clearInterval(timer);timer=setInterval(()=>{if(seconds.value>0)seconds.value--;else clearInterval(timer)},1000)
}
function lock(){if(seconds.value||!confirmation.value)return;const order=addOrder(task.value);confirmation.value=false;notify('演示接单成功，请按要求交付作品');router.push(`/creator/orders/${order.id}`)}
async function share(){try{await navigator.clipboard.writeText(window.location.href);notify('任务链接已复制')}catch{ElMessage.info('可复制浏览器地址分享任务')}}
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><main id="page-content" class="page-container app-ui task-detail-page">
 <template v-if="task"><div class="breadcrumbs"><RouterLink to="/">首页</RouterLink><span>/</span><RouterLink to="/tasks">任务广场</RouterLink><span>/</span><span>任务详情</span></div>
 <section class="detail-banner"><img src="/assets/task-square/chrome-banner.webp" alt=""/><div><h1>{{task.title}}</h1><div class="tag-row"><span>{{task.category}}</span><span>{{task.mode}}</span><span>{{task.status||'招募中'}}</span></div></div></section>
 <div class="columns wide-left"><div class="stack"><section class="panel detail-summary"><div><Layers/><span>赏金已托管<strong class="price-text">¥{{task.price.toLocaleString()}}</strong></span></div><div><CalendarDays/><span>交付期限<strong>接单后{{task.days}}天</strong></span></div><div><Users/><span>{{task.mode==='比稿'?'已投标':'剩余名额'}}<strong>{{task.mode==='比稿'?`${task.bids||0} 人`:`${Math.max(0,(task.capacity||1)-(task.filled||0))} / ${task.capacity||1}`}}</strong></span></div></section>
 <section class="panel"><h2>需求描述</h2><p>{{task.description}}</p><div class="divider"/><h2>交付要求</h2><div class="delivery-requirements"><p><ShieldCheck/>{{task.deliverables}}</p><p><ShieldCheck/>免费修改 {{task.revisions}} 轮，交付后请在平台内完成验收。</p><p><ShieldCheck/>保留商品包装与品牌信息，不得侵犯第三方权益。</p></div><div class="divider"/><div class="panel-title"><h2>参考素材</h2><span class="muted small"><LockKeyhole :size="14"/> 接单后可查看原始素材</span></div><div class="image-gallery"><div v-for="i in 3" :key="i" class="gallery-item"><img class="reference-image" :src="task.art==='skincare'?assetUrl(`pages/delivery-${i}.webp`):task.image" :alt="`${task.category}风格参考${i}`"/><span class="material-watermark">来单啦 · 参考预览</span></div></div><p class="field-help">参考图片用于展示风格，当前演示不提供商家原始素材。</p><div class="info-note"><Info/>平台外交易无保障，请在平台内沟通与交付。</div></section></div>
 <aside class="stack"><section class="panel"><h3><ShieldCheck :size="19" class="green-icon"/> 已认证商家 · 示例</h3><div class="person"><div class="avatar merchant-avatar">禾</div><div><h2>{{state.session.loggedIn?'青禾美妆':'已认证商家'}}</h2><span class="plain-tag">美妆护肤品牌</span></div></div><div class="merchant-metrics"><div>信用分<strong>100</strong></div><div>历史成单<strong>24</strong></div><div>好评率<strong>98%</strong></div></div><p class="field-help">以上为商家示例数据，仅用于界面展示。</p></section>
 <section class="panel"><h2>接单须知</h2><ul class="rules-list"><li>实名认证后可接单</li><li>免费修改 {{task.revisions}} 轮</li><li>验收通过后结算</li><li>作品提交后 72 小时自动验收</li></ul><div class="info-note"><ShieldCheck/>赏金托管，验收后结算</div></section>
 <template v-if="state.session.role!=='merchant'||!state.session.loggedIn"><el-button type="primary" size="large" class="full-button" :disabled="!available" @click="accept">{{available?(task.mode==='比稿'?'立即投标':'立即抢单'):'当前任务已结束招募'}}<ArrowRight/></el-button><div class="detail-secondary"><el-button @click="router.push('/messages?chat=merchant')"><MessageCircle/>联系商家</el-button><el-button :type="saved?'primary':'default'" plain @click="bookmark"><Star/>{{saved?'已收藏':'收藏任务'}}</el-button></div><p class="payout-note">预计实得 <strong class="price-text">¥{{money(income(task.price*100))}}</strong> · 平台服务费 15%</p></template>
 <template v-else><el-button type="primary" @click="router.push('/merchant/tasks')">管理我的任务</el-button><el-button @click="share">分享任务</el-button></template>
 </aside></div>
 <el-dialog v-model="confirmation" title="确认接受这份任务？" width="490px" :close-on-click-modal="false" class="refinement-dialog"><div class="app-ui dialog-stack"><p>{{task.title}}</p><div class="info-note">赏金 ¥{{task.price}} · {{task.days}} 天交付 · 免费修改 {{task.revisions}} 轮</div><p class="muted small">这是演示订单，不产生真实交易。请确认你能按时完成交付。</p></div><template #footer><el-button @click="confirmation=false">再想一下</el-button><el-button type="primary" :disabled="seconds>0" @click="lock">{{seconds>0?`请阅读须知 ${seconds}s`:'确认接单'}}</el-button></template></el-dialog>
 </template><el-empty v-else description="这份任务不存在或已下架"><el-button type="primary" @click="router.push('/tasks')">返回任务广场</el-button></el-empty>
</main></template>
<style scoped>
.detail-banner{background:#002bd7;color:#fff;min-height:118px;padding:23px 36px;border-radius:10px;position:relative;overflow:hidden;margin-bottom:22px}.detail-banner>img{position:absolute;right:0;top:0;width:48%;height:100%;object-fit:cover;object-position:right}.detail-banner>div{position:relative;z-index:1}.detail-banner h1{font-size:34px;margin-bottom:10px}.detail-banner .tag-row>span{border:1px solid #bbc9ff;border-radius:30px;padding:2px 14px;font-size:12px}.detail-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));padding:22px}.detail-summary>div{display:flex;align-items:flex-start;gap:16px;padding:0 22px;border-right:1px solid #d9dfeb}.detail-summary>div:first-child{padding-left:0}.detail-summary>div:last-child{border:0}.detail-summary>div>svg{margin-top:3px;width:25px;height:25px}.detail-summary span{font-size:13px}.detail-summary strong{display:block;font-size:25px;margin-top:2px}.delivery-requirements p{display:flex;align-items:flex-start;gap:8px}.delivery-requirements svg{width:18px;height:18px;color:#002bd7;margin-top:4px}.reference-image{width:100%;aspect-ratio:1.45;display:block;border-radius:6px;object-fit:cover;object-position:left}.material-watermark{position:absolute;bottom:12px;right:12px;color:#fff9;text-shadow:0 1px 3px #0005;font-size:12px;pointer-events:none}.merchant-metrics{display:grid;grid-template-columns:repeat(3,1fr);text-align:center;margin-top:24px;font-size:12px;color:#687083}.merchant-metrics strong{display:block;font-size:22px;color:#111}.merchant-avatar{background:#ede2ce;color:#a4885e}.green-icon{color:#19974f}.rules-list{padding-left:20px;line-height:2.3}.rules-list li::marker{color:var(--blue)}.detail-secondary{display:grid;grid-template-columns:1fr 1fr;gap:12px}.payout-note{text-align:center;font-size:12px}.payout-note strong{font-size:21px}.detail-summary+section p{line-height:1.9}
@media(max-width:1200px){.detail-summary>div{padding:0 12px;gap:10px}.detail-summary strong{font-size:20px}.detail-banner h1{font-size:29px}}@media(max-width:650px){.detail-banner{padding:22px}.detail-banner h1{font-size:24px}.detail-summary{padding:15px}.detail-summary>div>svg{display:none}.detail-summary span{font-size:10px}.detail-summary strong{font-size:16px}.detail-summary>div{padding:0 8px}.detail-secondary{gap:6px}.panel-title{flex-wrap:wrap}}
</style>
